export const patterns={natal:['Noite de Natal','Laços de carinho','Xadrez rubi','Bosque de papel'],aniversario:['Confete delicado','Céu de desejos','Fitas de festa','Bandeirinhas'],casamento:['Ramos em azul','Arcos rubi','Linho natural','Jardim em azul']};
export const themeGroup=occasion=>occasion==='natal'?'natal':occasion==='casamento'||occasion==='maes'?'casamento':'aniversario';
export const materials={algodao:'Papel de algodão',linho:'Linho',kraft:'Kraft natural'};
export function createMaterials(getState,onChange){
 const panel=document.createElement('details');panel.className='options-panel';panel.innerHTML='<summary>Material e estampas do tema</summary><div class="material-options"></div><p class="options-label">Escolha a estampa</p><div class="pattern-options"></div><button class="generate-variations" type="button">Gerar variações deste tema ↻</button><div class="variation-results" aria-live="polite"></div>';
 document.querySelector('.customizer-bottom').before(panel);
 const gallery=document.createElement('section');gallery.className='finish-gallery section-width';gallery.innerHTML='<div class="section-heading"><div><h2>O tema continua<br>em cada detalhe.</h2></div><p>Quatro estampas por ocasião.<br>Um acabamento para fazer seu.</p></div><div class="finish-grid"></div>';
 for(const [key,names] of Object.entries(patterns)){const group=document.createElement('article');group.className='finish-group';const title=document.createElement('h3');title.textContent=key==='natal'?'Natal':key==='casamento'?'Casamento':'Aniversário';const tiles=document.createElement('div');tiles.className='finish-tiles';names.forEach((name,i)=>{const b=document.createElement('button'),img=document.createElement('img'),label=document.createElement('span');img.src='assets/pattern-'+key+'-'+i+'.webp';img.alt='Estampa '+name;img.loading='lazy';label.textContent=name;b.append(img,label);b.addEventListener('click',()=>{onChange({occasion:key,pattern:key+'-'+i});document.getElementById('atelier').scrollIntoView({behavior:'smooth'});panel.open=true;});tiles.append(b);});group.append(title,tiles);gallery.querySelector('.finish-grid').append(group);}document.querySelector('.faq-section').before(gallery);
 for(const [id,label] of Object.entries(materials)){const b=document.createElement('button');b.dataset.material=id;b.className='material-choice';b.innerHTML='<span aria-hidden="true"></span>';b.firstChild.style.backgroundImage='url(assets/material-'+id+'.webp)';b.append(document.createTextNode(label));b.addEventListener('click',()=>onChange({texture:id}));panel.querySelector('.material-options').append(b);}
 let group='',round=0;
 function render(){const s=getState(),next=themeGroup(s.occasion);if(next!==group){group=next;const options=panel.querySelector('.pattern-options');options.replaceChildren();patterns[group].forEach((label,i)=>{const b=document.createElement('button');b.dataset.pattern=group+'-'+i;b.innerHTML='<img alt=""><span></span>';b.querySelector('img').src='assets/pattern-'+group+'-'+i+'.webp';b.querySelector('span').textContent=label;b.addEventListener('click',()=>onChange({pattern:b.dataset.pattern}));options.append(b);});panel.querySelector('.variation-results').replaceChildren();}panel.querySelectorAll('[data-material]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.material===s.texture)));panel.querySelectorAll('[data-pattern]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.pattern===s.pattern)));}
 panel.querySelector('.generate-variations').addEventListener('click',()=>{round++;const results=panel.querySelector('.variation-results');results.replaceChildren();const colors=['#B94162','#4A7294','#835A38','#5B486D'];for(let i=0;i<3;i++){const n=(round+i)%4,texture=Object.keys(materials)[(round+i)%3],pattern=group+'-'+n,color=colors[n];const b=document.createElement('button');b.className='variation-choice';const image=document.createElement('img');image.src='assets/pattern-'+pattern+'.webp';image.alt='';const label=document.createElement('span');label.textContent=patterns[group][n]+' · '+materials[texture];b.append(image,label);b.addEventListener('click',()=>onChange({pattern,texture,color}));results.append(b);}const note=document.createElement('p');note.textContent='Três combinações prontas. Suas fotos e palavras continuam com você.';results.append(note);});
 return {render};
}
